package com.example.storytv;
import android.content.*;import android.database.Cursor;import android.graphics.*;import android.net.Uri;import android.os.*;import java.io.*;
public class StreakArtProvider extends ContentProvider {
 public boolean onCreate(){return true;}public String getType(Uri uri){return "image/png";}public Cursor query(Uri uri,String[] p,String s,String[] a,String o){if(!"/status".equals(uri.getPath()))return null;android.database.MatrixCursor row=new android.database.MatrixCursor(new String[]{"streak"});row.addRow(new Object[]{StoryProgress.streak(getContext())});row.setNotificationUri(getContext().getContentResolver(),uri);return row;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
 public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{if(!"r".equals(mode)||!"/streak".equals(uri.getPath()))throw new FileNotFoundException();try{final ParcelFileDescriptor[] pipe=ParcelFileDescriptor.createPipe();final int n=StoryProgress.streak(getContext());new Thread(new Runnable(){public void run(){Bitmap b=Bitmap.createBitmap(640,360,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(0xfffff5e5);Paint p=new Paint(3);p.setColor(0xffffd384);c.drawRoundRect(20,20,620,340,30,30,p);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setColor(0xff385a59);p.setTextSize(30);c.drawText("STORY TIME",45,70,p);p.setTextSize(94);c.drawText("🔥  "+n,45,200,p);p.setTextSize(37);c.drawText("DAY STREAK",45,255,p);p.setTextSize(25);c.drawText("Open to read a story",45,310,p);try{OutputStream out=new ParcelFileDescriptor.AutoCloseOutputStream(pipe[1]);b.compress(Bitmap.CompressFormat.PNG,100,out);out.close();}catch(IOException ignored){}finally{b.recycle();}}}).start();return pipe[0];}catch(IOException e){throw new FileNotFoundException(e.getMessage());}}
}
